glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D texture_mask;
#endif
uniform input_param {
  uniform texture_mask1;
  float x_offset;
  float y_offset;
  float x_mul;
  float y_mul;
  float mask_a;
  bool  invert;
  bool  over_invert;
};
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  vec4 o_mask = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  vec4 texture_mask_tmp = texture(texture_mask, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture_mask
      texture_mask_tmp.a *= texture(texture_mask, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o_mask.rgb *= (texture_mask_tmp.rgb * texture_mask_tmp.rgb);
    o_mask.a *= texture_mask_tmp.a;
  #else
    o_mask *= texture_mask_tmp;
  #endif
    if(v_uv0.x >= x_offset && v_uv0.x <= (1.0/x_mul + x_offset) && v_uv0.y <= (1.0/y_mul + y_offset) && v_uv0.y >=  y_offset)
    {
      o_mask = texture2D(texture_mask, vec2(x_mul* (v_uv0.x - x_offset) ,y_mul * (v_uv0.y - y_offset)));
      if(invert == true)
      {
        o.a = o_mask.a * mask_a;
      }
      else
      {
        o.a *= 1.0 - o_mask.a * mask_a;
      }
    }
    else
    {
      if(over_invert == true)
      {
      }
      else
      {
        o.a = 0.0;
      }
    }
  #endif
  ALPHA_TEST(o);
  gl_FragColor = o;
}

